e careful, this will delete all files on the cloud storage related to the media library resources.', $this->text_domain); $translation_array['text']['are_u_sure_restore'] = __('Are you sure you want to restore this cloud storage?', $this->text_domain); $translation_array['text']['no_need_wait'] = __('You can close the window, no need to waiting.', $this->text_domain); $translation_array['text']['there_are_x_files_to_sync'] = __('There are <span id="qqworld-count">%s</span> files to sync.<bt />Now syncing, you can close current window.', $this->text_domain); $translation_array['text']['there_are_x_files_to_delete'] = __('There are <span id="qqworld-count">%s</span> files to delete.<bt />Now syncing, you can close current window.', $this->text_domain); $translation_array['text']['scanning_and_u_may_close_window'] = __('Scanning, You may close the window or waiting for finished.', $this->text_domain); $translation_array['text']['time_format_days'] = __('%d Days ', $this->text_domain); $translation_array['text']['time_format_hours'] = __('%d Hours ', $this->text_domain); $translation_array['text']['time_format_minutes'] = __('%d Minutes ', $this->text_domain); $translation_array['text']['time_format_seconds'] = __('%d Seconds', $this->text_domain); $translation_array['text']['from_the_next_collecting_time'] = __('<strong>%s</strong> Countdown: %s.', $this->text_domain); $translation_array['text']['syncing'] = __('Syncing.<span class="spinner is-active"></span>', $this->text_domain); } elseif ($screen->id == 'upload') { $translation_array['text']['synced'] = __('Synced.', $this->text_domain); $translation_array['text']['are_u_sure_delete_single'] = __('Are you sure you want to delete the cloud storage?', $this->text_domain); } $translation_array['cs'.'_acc'.'ess'.'ed'] = apply_filters( 'qq'.'world-coll'.'ecto'.'r-ser'.'ial-nu'.'mb'.'er', '' ) ? 1 : 0; return $translation_array; } public function get_metadata_table() { global $wpdb, $blog_id; return $blog_id == 1 ? $wpdb->prefix . 'cloud_storage_metadata' : $wpdb->prefix . $blog_id . '_cloud_storage_metadata'; } public function create_table() { global $wpdb; if ($wpdb->get_var("SHOW TABLES LIKE '{$this->get_metadata_table()}'") != $this->get_metadata_table()) { $sql = apply_filters( 'qqworld-collector-cloud-storage-get-metadata-table-sql', '', $this->get_metadata_table() ); if (!function_exists('dbDelta')) require(ABSPATH . 'wp-admin/includes/upgrade.php'); \dbDelta($sql); } } public function get_metadata($attachment_id, $classname) { global $wpdb; $sql = "SELECT `Metadata` FROM `{$this->get_metadata_table()}` WHERE `PostID` = {$attachment_id} AND `Type` = '{$classname}' LIMIT 1"; $row = $wpdb->get_row($sql); return $row ? unserialize($row->Metadata) : null; } public function set_metadata($attachment_id, $classname, $metadata) { global $wpdb; $table = $this->get_metadata_table(); $sql = "SELECT `ID` FROM `{$table}` WHERE `PostID` = {$attachment_id} AND `Type` = '{$classname}' LIMIT 1"; $row = $wpdb->get_row($sql); if ($row) { $wpdb->update( $table, array( 'Metadata' => serialize($metadata) ), array( 'ID' => $row->ID ), array( '%s'), array( '%d' ) ); } else { $wpdb->insert( $table, array( 'PostID' => $attachment_id, 'Type' => $classname, 'Metadata' => serialize($metadata) ), array( '%d', '%s', '%s') ); } } public function delete_metadata($attachment_id, $classname) { global $wpdb; $table = $this->get_metadata_table(); $sql = "SELECT `ID` FROM `{$table}` WHERE `PostID` = {$attachment_id} AND `Type` = '{$classname}' LIMIT 1"; $row = $wpdb->get_row($sql); if ($row) { $wpdb->delete( $table, array( 'ID' => $row->ID ), array( '%d' ) ); } } public function get_joinmode_url($attachment_id, $size = null, $style = null) { global $pagenow; $mime_type = get_post_mime_type($attachment_id); if ($pagenow != 'upload.php' || preg_match('/^image\//', $mime_type)) { $style = is_numeric($style) ? $style : $this->options->cloud_storage_jsonmode_style; switch ($style) { case 0: default: return $size && $size!='full' ? home_url('wp-json/cs/v1/' . $attachment_id . '/' . $size) : home_url('wp-json/cs/v1/' . $attachment_id); break; case 1: return $size && $size!='full' ? home_url('wp-json/cs/v1/' . $attachment_id . '/' . $size . '.jpg') : home_url('wp-json/cs/v1/' . $attachment_id . '.jpg'); break; case 2: return $size && $size!='full' ? home_url('wp-json/cs/v1/' . $attachment_id . '-' . $size) : home_url('wp-json/cs/v1/' . $attachment_id); break; case 3: return $size && $size!='full' ? home_url('wp-json/cs/v1/' . $attachment_id . '-' . $size . '.jpg') : home_url('wp-json/cs/v1/' . $attachment_id . '.jpg'); break; case 4: return $size && $size!='full' ? home_url('wp-json/cs/v1/' . $attachment_id . '_' . $size) : home_url('wp-json/cs/v1/' . $attachment_id); break; case 5: return $size && $size!='full' ? home_url('wp-json/cs/v1/' . $attachment_id . '_' . $size . '.jpg') : home_url('wp-json/cs/v1/' . $attachment_id . '.jpg'); break; } } } public function cron_delete_attachment($attachment_id) { remove_action( 'delete_attachment', array($this, 'delete_attachment') ); $sizes = array(); $sizes['full'] = get_attached_file( $attachment_id ); $path = dirname($sizes['full']); $metadata = wp_get_attachment_metadata($attachment_id); if (!empty($metadata['sizes'])) foreach ($metadata['sizes'] as $name => $size) { $sizes[$name] = $path . DIRECTORY_SEPARATOR . $size['file']; } foreach ($sizes as $size => $file) { @ unlink($file); } } public function get_attachments_list() { $guid = str_replace('-', '_', $_POST['guid']); $mode = $_POST['mode']; $paged = $_POST['paged']; switch ($mode) { case 'fast': $args = array( 'post_type' => 'attachment', 'meta_key' => "_sync_{$guid}", 'meta_value' => 1, 'meta_compare' => 'NOT EXISTS', 'posts_per_page' => 1000, 'offset' => 1000*$paged ); break; case 'smart': $args = array( 'post_type' => 'attachment', 'posts_per_page' => 1000, 'offset' => 1000*$paged ); break; case 'joinmode': $args = array( 'post_type' => 'attachment', 'posts_per_page' => 1000, 'o